const cfg = $('Workflow Configuration').first().json;
const raw = String(cfg.programCalendarIds || '');
const ids = raw.split(',').map(s => s.trim()).filter(s => s.length > 0);
return ids.map(id => ({ json: { calendarId: id } }));

// The Calendar q free text param also matches display names, so require an exact email match here.
const cfg = $('Workflow Configuration').first().json;
const leaver = String(cfg.leaverEmail || '').toLowerCase();
const findings = [];
for (const item of $input.all()) {
  const ev = item.json;
  if (!ev || ev.error || !ev.id) continue;
  const organizerEmail = String((ev.organizer && ev.organizer.email) || '').toLowerCase();
  const attendees = Array.isArray(ev.attendees) ? ev.attendees : [];
  const isOrganizer = organizerEmail === leaver;
  const isAttendee = attendees.some(a => String(a.email || '').toLowerCase() === leaver);
  if (!isOrganizer && !isAttendee) continue;
  const isRecurring = Array.isArray(ev.recurrence) && ev.recurrence.length > 0;
  findings.push({ json: {
    source: 'calendar',
    title: ev.summary || '(no title)',
    when: (ev.start && (ev.start.dateTime || ev.start.date)) || 'unknown start',
    link: ev.htmlLink || '',
    isRecurring: isRecurring,
    role: isOrganizer ? 'organizer' : 'attendee',
    bucket: (isOrganizer || isRecurring) ? 'needs_new_owner' : 'cancel_candidate'
  } });
}
return findings;

const cfg = $('Workflow Configuration').first().json;
const lastDay = String(cfg.lastWorkingDay || '');
const findings = [];
for (const item of $input.all()) {
  const t = item.json;
  if (!t || t.error || !t.gid) continue;
  if (t.completed === true) continue;
  const due = t.due_on || (t.due_at ? String(t.due_at).slice(0, 10) : null);
  if (due !== null && due <= lastDay) continue;
  findings.push({ json: {
    source: 'asana',
    title: t.name || '(untitled task)',
    when: due || 'no due date',
    link: t.permalink_url || '',
    isRecurring: false,
    role: 'assignee',
    projects: (Array.isArray(t.projects) ? t.projects : []).map(p => p.name || p.gid).join(', '),
    bucket: due ? 'needs_new_owner' : 'cancel_candidate'
  } });
}
return findings;

const cfg = $('Workflow Configuration').first().json;
const findings = $input.all().map(i => i.json).filter(f => f && f.source);
const needsOwner = findings.filter(f => f.bucket === 'needs_new_owner');
const cancels = findings.filter(f => f.bucket === 'cancel_candidate');
const recurringCount = findings.filter(f => f.isRecurring).length;
const asText = (content) => [{ type: 'text', text: { content: String(content).slice(0, 1900) } }];
const heading = (content) => ({ object: 'block', type: 'heading_2', heading_2: { rich_text: asText(content) } });
const paragraph = (content) => ({ object: 'block', type: 'paragraph', paragraph: { rich_text: asText(content) } });
const todo = (f) => {
  const prefix = f.isRecurring ? 'RECURRING ' : '';
  const source = f.source === 'calendar' ? 'Calendar' : 'Asana';
  const label = prefix + source + ': ' + f.title + ' (' + f.when + ', ' + f.role + ')';
  const rich = [{ type: 'text', text: { content: label.slice(0, 1800) } }];
  if (f.link) rich.push({ type: 'text', text: { content: ' open item', link: { url: f.link } } });
  return { object: 'block', type: 'to_do', to_do: { rich_text: rich, checked: false } };
};
const blocks = [];
blocks.push(paragraph('Departure sweep for ' + cfg.leaverEmail + ', last working day ' + cfg.lastWorkingDay + '. Reassign or cancel every item, then check it off.'));
blocks.push(heading('Needs a new owner (' + needsOwner.length + ')'));
for (const f of needsOwner) blocks.push(todo(f));
blocks.push(heading('Cancel candidates (' + cancels.length + ')'));
for (const f of cancels) blocks.push(todo(f));
return [{ json: {
  totalFindings: findings.length,
  needsOwnerCount: needsOwner.length,
  cancelCount: cancels.length,
  recurringCount: recurringCount,
  blocks: blocks
} }];

// Notion caps block appends at 100 blocks per call, so heavy leavers need chunked appends.
const manifest = $('Bucket Findings For Handover').first().json;
const page = $input.first().json;
const blocks = Array.isArray(manifest.blocks) ? manifest.blocks : [];
const chunks = [];
for (let i = 0; i < blocks.length; i += 100) {
  chunks.push({ json: { pageId: page.id, chunkIndex: chunks.length, children: blocks.slice(i, i + 100) } });
}
return chunks;

const manifest = $('Bucket Findings For Handover').first().json;
const page = $('Create Handover Manifest Page').first().json;
return [{ json: {
  pageUrl: page.url || '',
  totalFindings: manifest.totalFindings,
  needsOwnerCount: manifest.needsOwnerCount,
  cancelCount: manifest.cancelCount,
  recurringCount: manifest.recurringCount,
  appendCalls: $input.all().length
} }];
